// Author: MiYu. Original Human06 outcome events, interlude transition and Human07 hero cache run in isolated sessions.
#include "session.h"
#include "setup.h"
#include <bit>
#include <filesystem>
#include <iostream>
#include <tuple>
#include <vector>

using namespace war3;
namespace {
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
float number(jass::Value value){return std::bit_cast<float>(value.bits);}
std::unique_ptr<ScriptSession> start(const wchar_t* root,const char* path){
    Archives archives(root);auto bytes=archives.readCandidates({path},ArchiveScope::Common);if(!bytes)throw std::runtime_error(std::string("Campaign map missing: ")+path);archives.mountMap(std::make_shared<const Bytes>(bytes->bytes),path);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);auto session=std::make_unique<ScriptSession>(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));session->campaignContext(true,1);session->attachWorld(std::move(world));session->audioSimulationClock();session->audioMuted(true);session->configure();PlayerSetup setup(info,session->config());session->applySetup(setup);session->startMain();return session;
}
void advanceToGameplay(ScriptSession& session){for(int i=0;i<1320;++i)session.advance(.25);require(session.exitRequest()==SessionExit::None && session.userControl(),"Human06 did not reach gameplay");}
void continueDialog(ScriptSession& session){for(auto& [id,dialog]:session.dialogs())if(dialog->owners){require(!dialog->buttons.empty() && session.clickDialog(session.localPlayer().value_or(0),dialog->buttons.front()),"Outcome dialog could not continue");break;}}
void victory(const wchar_t* root){
    {auto session=start(root,"Maps\\Campaign\\Human06.w3m");advanceToGameplay(*session);auto& vm=session->runtime();auto hero=vm.global("udg_ArthasVariable");require(session->units().contains(hero.bits),"Human06 Arthas missing");auto u=session->units().at(hero.bits);vm.invoke("SetHeroLevel",std::array{hero,vm.integer(7),vm.boolean(false)});vm.invoke("SetUnitUserData",std::array{hero,vm.integer(2468)});auto real=[&](float n){return vm.real(jass::Real::fromBits(std::bit_cast<unsigned>(n)));};
        for(int i=0;i<100;++i){auto zombie=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100002),vm.integer(int(ObjectData::code("nzom"))),vm.real(u->x),vm.real(u->y),real(0)});auto damaged=vm.invoke("UnitDamageTarget",std::array{hero,zombie,real(10000),vm.boolean(true),vm.boolean(false),vm.handle("attacktype",0),vm.handle("damagetype",4),vm.handle("weapontype",0)});require(damaged.bits!=0,"Human06 objective damage rejected");}require(number(vm.global("udg_ArthasDenials"))==100,"Human06 objective did not reach 100 through death events");for(int i=0;i<1800 && session->exitRequest()==SessionExit::None;++i){session->advance(.25);continueDialog(*session);}require(session->results()[1] && *session->results()[1]==0 && session->exitRequest()==SessionExit::ChangeLevel && session->nextLevel()=="Maps\\Campaign\\Human06Interlude.w3m","Human06 did not enter its victory interlude");}
    {auto session=start(root,"Maps\\Campaign\\Human06Interlude.w3m");bool skipped=false;for(int i=0;i<1400 && session->exitRequest()==SessionExit::None;++i){session->advance(.25);if(i==120)skipped=session->endCinematic(session->localPlayer().value_or(9));continueDialog(*session);}require(skipped && session->exitRequest()==SessionExit::ChangeLevel && session->nextLevel()=="Maps\\Campaign\\Human07.w3m","Human06 interlude did not skip into Human07");}
    {auto session=start(root,"Maps\\Campaign\\Human07.w3m");session->advance(20);auto& vm=session->runtime();auto hero=vm.global("udg_Arthas");require(session->units().contains(hero.bits) && vm.invoke("GetHeroLevel",std::array{hero}).bits==7 && vm.invoke("GetUnitUserData",std::array{hero}).bits==2468,"Human07 did not restore the saved Arthas state");while(session->simulationTime()<90)session->advance(.25);auto rect=vm.global("gg_rct_BeginMuradinIntro");vm.invoke("SetUnitPosition",std::array{hero,vm.invoke("GetRectCenterX",std::array{rect}),vm.invoke("GetRectCenterY",std::array{rect})});while(session->simulationTime()<200)session->advance(.25);auto muradin=vm.global("udg_Muradin");require(session->units().contains(muradin.bits) && session->userControl(),"Human07 Muradin encounter did not finish");vm.invoke("SetHeroLevel",std::array{muradin,vm.integer(6),vm.boolean(false)});vm.invoke("SetUnitUserData",std::array{muradin,vm.integer(3579)});std::vector<std::uint32_t> buildings;for(auto& [id,u]:session->units())if(u->owner==6 && u->building && ObjectData::name(u->type)!="uzig" && ObjectData::name(u->type)!="uzg1" && number(vm.invoke("GetWidgetLife",std::array{vm.handle("unit",id)}))>0)buildings.push_back(id);require(!buildings.empty(),"Human07 objective buildings missing");for(auto id:buildings){auto h=vm.handle("unit",id);vm.invoke("SetUnitInvulnerable",std::array{h,vm.boolean(false)});vm.invoke("KillUnit",std::array{h});}for(int i=0;i<1400 && session->exitRequest()==SessionExit::None;++i){session->advance(.25);continueDialog(*session);}require(session->results()[1] && *session->results()[1]==0 && session->exitRequest()==SessionExit::ChangeLevel && session->nextLevel()=="Maps\\Campaign\\Human08.w3m","Human07 did not enter Human08 after its objective");}
    {auto session=start(root,"Maps\\Campaign\\Human08.w3m");session->advance(20);auto& vm=session->runtime();for(auto [name,level,data]:{std::tuple{"udg_Arthas",7u,2468u},std::tuple{"udg_Muradin",6u,3579u}}){auto hero=vm.global(name);require(session->units().contains(hero.bits) && vm.invoke("GetHeroLevel",std::array{hero}).bits==level && vm.invoke("GetUnitUserData",std::array{hero}).bits==data,"Human08 did not restore both heroes");}}std::cout<<"PASS Human06 and Human07 victories with Human08 hero cache\n";
}
void defeat(const wchar_t* root){
    auto session=start(root,"Maps\\Campaign\\Human06.w3m");advanceToGameplay(*session);auto& vm=session->runtime();auto hero=vm.global("udg_MalganisVariable");require(session->units().contains(hero.bits),"Human06 Malganis missing");auto u=session->units().at(hero.bits);vm.invoke("PauseCompAI",std::array{vm.handle("player",0x100006),vm.boolean(true)});for(int i=0;i<99;++i)vm.invoke("Trig_Malganis_Gains_Convert_Actions");require(number(vm.global("udg_MalganisConversions"))==99,"Could not prepare conversion threshold");auto real=[&](float n){return vm.real(jass::Real::fromBits(std::bit_cast<unsigned>(n)));};auto target=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100008),vm.integer(int(ObjectData::code("nC00"))),vm.real(u->x),vm.real(u->y),real(0)});vm.invoke("SetUnitPathing",std::array{target,vm.boolean(false)});vm.invoke("SetUnitMoveSpeed",std::array{target,real(0)});require(vm.invoke("IssueTargetOrder",std::array{hero,vm.string("darkconversion"),target}).bits!=0,"Final conversion order rejected");for(int i=0;i<1800 && session->exitRequest()==SessionExit::None;++i){session->advance(.25);continueDialog(*session);}require(number(vm.global("udg_MalganisConversions"))==100 && vm.global("udg_GameOver").bits && session->results()[1] && *session->results()[1]==1 && session->exitRequest()==SessionExit::Restart,"Human06 did not enter its defeat and restart flow");std::cout<<"PASS Human06 final conversion, defeat and restart\n";
}
}
int wmain(int argc,wchar_t** argv){try{if(argc!=4)throw std::runtime_error("Usage: war3_human_campaign_chain_tests <data-root> <new-absolute-user-dir> <victory|defeat>");std::filesystem::path user(argv[2]);require(user.is_absolute() && std::filesystem::create_directory(user) && SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()),"User directory must be a new absolute directory with an existing parent");std::wstring_view mode=argv[3];if(mode==L"victory")victory(argv[1]);else if(mode==L"defeat")defeat(argv[1]);else throw std::runtime_error("Unknown campaign check mode");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
